<script setup lang="ts">
import { computed, ref } from 'vue';
import DashboardCard from './DashboardCard.vue';
import { compactMoney, money } from '../format';
const props = defineProps<{ series: {collected_minor:number;expected_minor:number;pending_minor:number}[]; months: string[] }>();
const range = ref('6');
const series = computed(()=>props.series.slice(-Number(range.value)));
const labels = computed(()=>props.months.slice(-Number(range.value)));
const max = computed(()=>Math.max(...series.value.map(s=>s.expected_minor),1)*1.1);
const points = (key:'expected_minor'|'collected_minor') => series.value.map((s,i)=>`${55+i*(490/Math.max(series.value.length-1,1))},${166-s[key]/max.value*135}`).join(' ');
</script>
<template><DashboardCard title="Finance overview" subtitle="School fees · not platform subscriptions" sample><template #action><select v-model="range" class="compact-select" aria-label="Finance chart period"><option value="6">Last 6 months</option><option value="3">Last 3 months</option></select></template><div class="finance-chart-summary"><div><span>Total expected</span><strong>{{ money(series.reduce((a,s)=>a+s.expected_minor,0)) }}</strong></div><div><span>Sample collected</span><strong>{{ money(series.reduce((a,s)=>a+s.collected_minor,0)) }}</strong></div><div class="finance-chart-legend"><span><i/>Expected</span><span><i/>Collected</span></div></div><div class="finance-chart"><svg viewBox="0 0 570 200" role="img" :aria-label="`Sample fee totals, ${labels.join(' to ')}. ${series.map((s,i)=>`${labels[i]}: expected ${money(s.expected_minor)}, collected ${money(s.collected_minor)}`).join('; ')}`"><defs><linearGradient id="school-finance-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#188d76" stop-opacity=".17"/><stop offset="100%" stop-color="#188d76" stop-opacity="0"/></linearGradient></defs><g v-for="n in [0,1,2,3]" :key="n"><line x1="50" x2="550" :y1="166-n*45" :y2="166-n*45"/><text x="39" :y="170-n*45" text-anchor="end">{{ compactMoney(max*n/3) }}</text></g><polygon :points="`55,166 ${points('collected_minor')} 545,166`" fill="url(#school-finance-fill)"/><polyline :points="points('expected_minor')" fill="none" stroke="#b4cac4" stroke-width="2" stroke-dasharray="5 4"/><polyline :points="points('collected_minor')" fill="none" stroke="#188d76" stroke-width="2.7" stroke-linejoin="round"/><circle v-for="(s,i) in series" :key="i" :cx="55+i*(490/Math.max(series.length-1,1))" :cy="166-s.collected_minor/max*135" r="3" fill="#188d76"/><text v-for="(label,i) in labels" :key="label" :x="55+i*(490/Math.max(series.length-1,1))" y="192" text-anchor="middle">{{ label }}</text></svg></div></DashboardCard></template>
